/// Outcome of one package's pre-warm run.
class PrewarmReport {
  final List<String> downloaded;
  final List<String> skipped;

  const PrewarmReport(this.downloaded, this.skipped);
}

// ── Inlined SHA-256 (FIPS 180-4) ────────────────────────────────────────
//
// package:crypto is deliberately not imported (see the header note): the
// hook-free `dart --disable-dart-dev` invocation resolves no package
// config. The round constants and the compression function are the
// standard algorithm; the only subtlety on Dart's 64-bit ints is masking
// every arithmetic result back to 32 bits.

const List<int> _sha256K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
  0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
  0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
  0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
  0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
  0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

int _rotr32(int x, int n) => ((x >>> n) | (x << (32 - n))) & 0xFFFFFFFF;

/// The lowercase hex SHA-256 digest of [message] — byte-identical to
/// `package:crypto`'s `sha256.convert(message).toString()` (the unit tests
/// cross-verify the two implementations against the fixture pins).
String sha256Hex(List<int> message) {
  const mask = 0xFFFFFFFF;
  final bitLength = message.length * 8;
  final padded = BytesBuilder(copy: false);
  padded.add(message);
  padded.addByte(0x80);
  final zeroPad = (56 - ((message.length + 1) % 64)) % 64;
  if (zeroPad > 0) padded.add(Uint8List(zeroPad));
  for (var shift = 56; shift >= 0; shift -= 8) {
    padded.addByte((bitLength >>> shift) & 0xff);
  }
  final data = padded.takeBytes();

  var h0 = 0x6a09e667,
      h1 = 0xbb67ae85,
      h2 = 0x3c6ef372,
      h3 = 0xa54ff53a,
      h4 = 0x510e527f,
      h5 = 0x9b05688c,
      h6 = 0x1f83d9ab,
      h7 = 0x5be0cd19;

  for (var block = 0; block < data.length; block += 64) {
    final w = List<int>.filled(64, 0);
    for (var t = 0; t < 16; t++) {
      final i = block + t * 4;
      w[t] = (data[i] << 24) | (data[i + 1] << 16) | (data[i + 2] << 8) |
          data[i + 3];
    }
    for (var t = 16; t < 64; t++) {
      final s0 = _rotr32(w[t - 15], 7) ^ _rotr32(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      final s1 = _rotr32(w[t - 2], 17) ^ _rotr32(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) & mask;
    }

    var a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
    for (var t = 0; t < 64; t++) {
      final bigS1 = _rotr32(e, 6) ^ _rotr32(e, 11) ^ _rotr32(e, 25);
      final ch = (e & f) ^ ((~e & mask) & g);
      final temp1 = (h + bigS1 + ch + _sha256K[t] + w[t]) & mask;
      final bigS0 = _rotr32(a, 2) ^ _rotr32(a, 13) ^ _rotr32(a, 22);
      final maj = (a & b) ^ (a & c) ^ (b & c);
      final temp2 = (bigS0 + maj) & mask;
      h = g;
      g = f;
      f = e;
      e = (d + temp1) & mask;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) & mask;
    }
    h0 = (h0 + a) & mask;
    h1 = (h1 + b) & mask;
    h2 = (h2 + c) & mask;
    h3 = (h3 + d) & mask;
    h4 = (h4 + e) & mask;
    h5 = (h5 + f) & mask;
    h6 = (h6 + g) & mask;
    h7 = (h7 + h) & mask;
  }

  final out = BytesBuilder(copy: false);
  for (final word in [h0, h1, h2, h3, h4, h5, h6, h7]) {
    for (var shift = 28; shift >= 0; shift -= 4) {
      out.addByte((word >>> shift) & 0xf);
    }
  }
  final digestBytes = out.takeBytes();
  final hex = StringBuffer();
  for (final byte in digestBytes) {
    hex.write(byte.toRadixString(16).padLeft(2, '0'));
  }
  return hex.toString();
}

